return [
  {
    json: {
      candidate_name: "Demo Candidate",
      email: "candidate@example.com",
      resume_text: "I am an AI Automation Engineer with 6 years of professional experience in Python, n8n, APIs, AI Automation, and JavaScript. I have extensive experience designing and building AI-powered automation workflows and enterprise integrations. I hold a Master's degree in Artificial Intelligence and have successfully delivered multiple automation projects using n8n, Python, APIs, and machine learning.",
      job_title: "AI Automation Engineer",
      job_requirements: ["Python", "n8n", "APIs", "AI Automation", "JavaScript"]
    }
  }
];

const input = $input.first().json;

const candidate_name = input.candidate_name || "";
const email = input.email || "";
const resume_text = input.resume_text || "";
const job_title = input.job_title || "";
const job_requirements = Array.isArray(input.job_requirements) ? input.job_requirements : [];

const geminiPrompt = `You are an expert technical recruiter and resume analyst.

Analyze the following candidate resume against the job title and requirements.

Job Title: ${job_title}
Job Requirements: ${job_requirements.join(", ")}

Candidate Resume:
"""
${resume_text}
"""

Return ONLY valid JSON (no markdown, no code fences, no extra text) in EXACTLY this format:
{
  "skills": [],
  "experience_years": 0,
  "education": "",
  "strengths": [],
  "weaknesses": [],
  "suitability": "High/Medium/Low",
  "analysis_summary": ""
}`;

return [
  {
    json: {
      candidate_name,
      email,
      resume_text,
      job_title,
      job_requirements,
      geminiPrompt
    }
  }
];

const item = $input.first().json;

let rawText = "";
try {
  rawText = item.candidates[0].content.parts[0].text;
} catch (e) {
  rawText = typeof item === "string" ? item : JSON.stringify(item);
}

function extractJson(text) {
  if (!text || typeof text !== "string") return null;

  let cleaned = text.trim();

  cleaned = cleaned.replace(/```json/gi, "").replace(/```/g, "").trim();

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // fall through to brace extraction
  }

  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    const candidateJson = cleaned.substring(firstBrace, lastBrace + 1);
    try {
      return JSON.parse(candidateJson);
    } catch (e2) {
      // fall through
    }
  }

  return null;
}

let parsed = extractJson(rawText);

if (!parsed) {
  parsed = {
    skills: [],
    experience_years: 0,
    education: "",
    strengths: [],
    weaknesses: [],
    suitability: "Low",
    analysis_summary: "AI response could not be parsed. Raw response: " + String(rawText).substring(0, 500)
  };
}

parsed.skills = Array.isArray(parsed.skills) ? parsed.skills : [];
parsed.experience_years = Number(parsed.experience_years) || 0;
parsed.education = typeof parsed.education === "string" ? parsed.education : "";
parsed.strengths = Array.isArray(parsed.strengths) ? parsed.strengths : [];
parsed.weaknesses = Array.isArray(parsed.weaknesses) ? parsed.weaknesses : [];
parsed.suitability = ["High", "Medium", "Low"].includes(parsed.suitability) ? parsed.suitability : "Low";
parsed.analysis_summary = typeof parsed.analysis_summary === "string" ? parsed.analysis_summary : "";

const prepared = $node["Prepare Candidate & Job Data"].json;

return [
  {
    json: {
      candidate_name: prepared.candidate_name,
      email: prepared.email,
      job_title: prepared.job_title,
      job_requirements: prepared.job_requirements,
      ai_analysis: parsed
    }
  }
];

const item = $input.first().json;

const jobRequirements = Array.isArray(item.job_requirements) ? item.job_requirements : [];
const candidateSkills = Array.isArray(item.ai_analysis.skills) ? item.ai_analysis.skills : [];

const normalize = (s) => String(s).trim().toLowerCase();

const normalizedCandidateSkills = candidateSkills.map(normalize);
const normalizedJobRequirements = jobRequirements.map(normalize);

const matched_skills = [];
const missing_skills = [];

normalizedJobRequirements.forEach((req, index) => {
  const isMatch = normalizedCandidateSkills.some((skill) =>
    skill.includes(req) || req.includes(skill)
  );
  if (isMatch) {
    matched_skills.push(jobRequirements[index]);
  } else {
    missing_skills.push(jobRequirements[index]);
  }
});

const skill_match_percentage = normalizedJobRequirements.length > 0
  ? Math.round((matched_skills.length / normalizedJobRequirements.length) * 100)
  : 0;

return [
  {
    json: {
      ...item,
      matched_skills,
      missing_skills,
      skill_match_percentage
    }
  }
];

const item = $input.first().json;

const skill_match_percentage = Number(item.skill_match_percentage) || 0;
const experience_years = Number(item.ai_analysis.experience_years) || 0;
const education = String(item.ai_analysis.education || "").toLowerCase();
const suitability = item.ai_analysis.suitability || "Low";

const skillScore = Math.round((skill_match_percentage / 100) * 50);

let experienceScore = 0;
if (experience_years >= 5) {
  experienceScore = 20;
} else if (experience_years >= 3) {
  experienceScore = 15;
} else if (experience_years >= 1) {
  experienceScore = 10;
} else if (experience_years > 0) {
  experienceScore = 5;
}

let educationScore = 0;
if (education.includes("phd") || education.includes("doctorate")) {
  educationScore = 10;
} else if (education.includes("master")) {
  educationScore = 8;
} else if (education.includes("bachelor") || education.includes("degree")) {
  educationScore = 6;
} else if (education.includes("diploma") || education.includes("certificate")) {
  educationScore = 4;
} else if (education.length > 0) {
  educationScore = 2;
}

let suitabilityScore = 0;
if (suitability === "High") {
  suitabilityScore = 20;
} else if (suitability === "Medium") {
  suitabilityScore = 10;
} else {
  suitabilityScore = 0;
}

const candidate_score = skillScore + experienceScore + educationScore + suitabilityScore;

return [
  {
    json: {
      ...item,
      score_breakdown: {
        skill_score: skillScore,
        experience_score: experienceScore,
        education_score: educationScore,
        suitability_score: suitabilityScore
      },
      candidate_score
    }
  }
];

const item = $input.first().json;

const candidate_score = Number(item.candidate_score) || 0;

let recommendation;
if (candidate_score >= 80) {
  recommendation = "Shortlist";
} else if (candidate_score >= 50) {
  recommendation = "Review";
} else {
  recommendation = "Reject";
}

return [
  {
    json: {
      candidate_name: item.candidate_name || "",
      email: item.email || "",
      job_title: item.job_title || "",
      skills: Array.isArray(item.ai_analysis.skills) ? item.ai_analysis.skills : [],
      experience_years: Number(item.ai_analysis.experience_years) || 0,
      education: item.ai_analysis.education || "",
      matched_skills: item.matched_skills || [],
      missing_skills: item.missing_skills || [],
      skill_match_percentage: item.skill_match_percentage || 0,
      candidate_score: candidate_score,
      recommendation: recommendation,
      analysis_summary: item.ai_analysis.analysis_summary || ""
    }
  }
];

